#!/usr/bin/env bash
# Verifier driver for step 06 (quiche 0.11.0).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 06
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=6
step_tag=0.11.0
log_dir=/tmp/quiche-verifier-06
harness=/tmp/quiche-harness-06
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=2d8c4f3ed85f88d355bc2e25d8b592574be30f704efe78c1210462493329fae7
expected_asset_files=32

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T1: A 64 KiB generated body still crosses the candidate's own HTTP/3 server and client, byte for byte, with the client exiting 0. The programs are different programs now — `quiche-server --listen/--cert/--key/--root` and `quiche-client --no-verify <url>` in place of the no-argument `examples/http3-server` — so this is the group that catches a workspace reshuffle that moved the code but broke the request path. Both are told `--http-version HTTP/3` explicitly, so that a candidate whose default happens to be HTTP/0.9 is still asked the question step 01 asked.
gate_check reg-01-h3-get run_case reg-01-h3-get reg reg_01_h3_get
# T3: A 64 KiB transfer through a 4096-byte stream window still takes many rounds and still arrives intact. The window is pinned with `set_max_stream_window(4096)` so that the claim is the same claim step 01 made — the receiver extends its limit by one window at a time and the sender respects it — rather than a claim about the autotuner this step adds. The group requires the first `stream_send` to accept exactly 4096 bytes and no more, the capacity to read 0 while those bytes are in flight, a further `stream_send` at that point to place nothing and say so with `Err(Error::Done)`, every subsequent round to be offered no more than one window, the transfer to need at least 16 rounds, and all 65536 bytes to arrive in order.
gate_check reg-01-flow-control run_case reg-01-flow-control reg reg_01_flow_control
# T5: The three bytes `0e 01 ff` — the frame type DUPLICATE_PUSH carried at draft-27, a length of 1 and one payload byte — written by hand onto an HTTP/3 request stream ahead of a real HEADERS frame. The expected outcome is a silent discard: the unknown frame is skipped, the HEADERS frame that follows it on the same stream is delivered with its `:path` intact, and neither endpoint closes the connection. The frame type is still undefined at 0.11.0, so the answer is still "ignore it", and the group is here because this step rewrites the crate's directory layout and its HTTP/3 settings table around the frame parser that has to keep doing that.
gate_check reg-02-duplicate-push-removed run_case reg-02-duplicate-push-removed reg reg_02_duplicate_push_removed
# T1: The whole stack, as a user of it would drive it. One `quiche-server` on a free ephemeral port with a certificate, a key and a document root the grader chose, and then two separate `quiche-client` invocations against it: one for a 96 KiB generated body, which must arrive byte for byte on stdout with exit status 0, and one for `/`, which must be answered with the index file. The server must still be running afterwards. The client is not told which HTTP version to use, so this group is satisfied by whichever one the two ends negotiate between themselves. If the workspace does not build both binaries, if the flags are not honoured, if the handshake does not complete or if the stack cannot move a body of that size over the protocol it chose, this group fails and it is the first thing to look at.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T4: The shape of the produced tree, read structurally and not searched for identifiers. The repository root must carry a workspace manifest whose `members` list names three directories and whose `exclude` list names `fuzz` and `tools/http3_test` — two real, nested crates that are not workspace members and would otherwise make cargo warn about an unlisted manifest; `quiche/Cargo.toml` must declare a package called `quiche` whose `version` field reads exactly `0.11.0` — the version is parsed out and compared, not skimmed past — with its library root at `quiche/src/lib.rs`; `qlog/Cargo.toml` must declare a separate package called `qlog`; `apps` must declare the package `quiche_apps`; and there must be no `src/lib.rs` at the repository root, because the crate moved rather than being copied. The workspace's shared `target/debug/` must then hold two executables named `quiche-client` and `quiche-server`. That last check is also where the previous three milestones' no-argument `examples/http3-server` stops mattering, and it is worth being exact about how. The example *source* is still in the tree — it moved with the crate, to `quiche/examples/http3-server.rs`, and deleting it is not required. What changed is that no group resolves it by name any more: the T1 groups at this step ask for `quiche-server`, so a tree that still builds the example but does not produce `quiche-server` fails here and at every T1 group, while a tree that produces both is fine. The grader reads the manifests with a TOML parser and checks the files on disk; it does not grep any source file.
score_if cap-workspace-layout run_case cap-workspace-layout cap cap_workspace_layout
# T1: Two of the candidate's own processes on loopback UDP, configured entirely from the command line. The grader picks a free ephemeral port, writes a document root under its own scratch directory containing a 24 KiB generated body and a differently named index file, and starts `quiche-server --listen 127.0.0.1:PORT --cert ... --key ... --root ... --index ...`. It then requires that the server bound exactly that port; that `quiche-client --no-verify https://127.0.0.1:PORT/payload.bin` exits 0 having written the 24 KiB body to stdout byte for byte, with no framing and no headers; that the same client with `-n 3 --dump-responses DIR` exits 0 having written nothing at all to stdout and leaving exactly three files in `DIR`, named `payload.bin`, `payload.bin.2` and `payload.bin.3`, each of them the whole 24 KiB body; that `https://127.0.0.1:PORT/` is answered with the contents of the file `--index` named rather than with `index.html`; and that a path outside the root is answered `Not Found!` without killing the server. Every one of those facts is a flag the previous milestone's binaries had no way to accept. The three responses are checked through `--dump-responses` rather than on stdout because the three requests are in flight together and their bodies interleave there. Four more flags are checked the same way, each against its own fresh server/client pair: `--dump-packets DIR` must leave one raw file per incoming datagram in `DIR`, on both the server started above and a client started below, before any header of that datagram is even parsed -- checked by requiring at least one dumped file to still carry the long-header form bit every Initial packet sets. `--no-retry` is checked by parsing the raw long-header bytes `--dump-packets` leaves behind rather than by reading any process's own output: without the flag, a token-less Initial must be met with a genuine, real-version Retry packet (type bits `0b11` at RFC 9000's version-independent header offset); with it, no such packet may appear anywhere in what the client received. `--wire-version` is checked the same way in the other direction: the client's own default (`babababa`) is a reserved "grease" version that always trips version negotiation first, so an explicitly chosen, distinct grease value must be the very first version the server ever receives. `--session-file PATH` is checked by requiring the named file to exist and be non-empty after a connection completes, since a client that never called into that TLS-session-caching path would leave nothing there. `-H`/`--header` is deliberately out of scope at this group and at this step: `build_h3_response` (the reference server's only request-header consumer) reads exactly `:scheme`, `:authority`/`host`, `:path`, `:method` and `priority` and silently drops every other header, so a header this flag adds has no server-observable effect through any channel a group here can reach short of decrypting and QPACK-decoding the request -- `--dump-packets` captures ciphertext, and no process's own stdout/stderr/qlog output echoes request headers back. Building that decode capability for one low-priority CLI flag would be a materially larger verifier than everything else in this group put together.
score_if cap-apps-cli-flags run_case cap-apps-cli-flags cap cap_apps_cli_flags
# T4: The trace file a real connection leaves behind, parsed as JSON Text Sequences. The grader runs a request against the candidate's own server with `QLOGDIR` pointing at an empty directory, then requires: exactly one `server-*.sqlog` and one `client-*.sqlog`; every record in each file prefixed with the byte `0x1e` and parsing as a single JSON object; a first record whose `qlog_version` is `"0.3"`, whose `qlog_format` is `"JSON-SEQ"` and whose `trace.vantage_point.type` is `"server"` on the server side and `"client"` on the client side; every later record carrying exactly the keys `time`, `name` and `data`; and the set of `name` values being exactly `transport:parameters_set`, `transport:packet_sent`, `transport:packet_received`, `transport:data_moved` and `recovery:metrics_updated` — no more, no fewer. It then requires that the `parameters_set` record with `"owner":"local"` carries the four values the server was given on its command line (`--max-data`, `--max-stream-data`, `--max-streams-bidi`, `--idle-timeout`) under their RFC 9000 names, which is what makes this a statement about a trace of the connection that happened and not about a template. The same record is also required to carry the correct value for every other field the local transport parameters expose: `initial_max_stream_data_uni` and `initial_max_streams_uni` (the apps binary feeds these from `--max-stream-data`/its own default, respectively), `max_udp_payload_size` (the 1350-byte constant every quiche-apps binary hardcodes), `ack_delay_exponent`, `max_ack_delay` and `active_connection_id_limit` (quiche's own built-in transport-parameter defaults), and `disable_active_migration` (hardcoded `true` by the apps binary). The `parameters_set` record with `"owner":"remote"` -- the server's report of what quiche-client sent it -- is held to the same standard: since the client in this connection is launched with none of the matching CLI overrides, every one of these fields is checked against quiche-client's own docopt default or the same apps/quiche constant, not merely checked for presence or counted. No substring search is used anywhere. A second connection, this time with the client started under a tiny, pinned `--max-stream-window` (and a matching small `--max-stream-data`) against a body many times that size, requires that the client's own trace show at least ten MAX_STREAM_DATA extensions on the response stream and that no single extension grow the offered window by more than four times the configured ceiling. `--max-stream-window` and `--max-stream-data` are CLI-only plumbing on top of the `Config` receiver-window and stream-window setters -- those setters are already exercised in-memory by `cap-stream-window-autotune` -- so this is the check that these two flags actually reach them, rather than being silently ignored in favour of the built-in defaults. `--max-window`, the connection-level sibling, is parsed by the binaries but is passed by no group at this step, so nothing here observes whether it is wired up.
score_if cap-qlog-jsonseq run_case cap-qlog-jsonseq cap cap_qlog_jsonseq
# T2: The grader builds and encrypts a 1-RTT packet of its own and requires the candidate's server to read it. Packet protection is entirely `quiche_verifier_support`'s: the client's application traffic secret is taken out of the candidate through the standard NSS keylog hook, the AEAD, the nonce and the header-protection mask are the verifier's, and the verifier confirms its keys are right by first decrypting one of the candidate's own 1-RTT packets with them. The payload is two frames: an ACK frame of type `0x03` acknowledging packet 0 with ECN counts `(ECT0, ECT1, CE) = (7, 11, 3)`, followed by a STREAM frame carrying 64 generated bytes on stream 8. Feeding that packet to the server must return `Ok`, and `stream_recv` on stream 8 must then yield those 64 bytes exactly — which is only possible if all three ECN varints were consumed and the parser arrived at the frame after them. The same packet at the previous milestone is `Error::InvalidFrame` and a `FRAME_ENCODING_ERROR` connection close, so the group is also checked in the other direction. The verifier drains every packet the server then wants to send, decrypts each one with its own keys and decodes the frames itself: none of them may be a `CONNECTION_CLOSE`, one of them must carry an ACK range covering the injected packet number, and the server must be neither closed nor draining afterwards. The drain is done by hand rather than by exchanging with the pair, because the injected packet carries a packet number the pair's own client never sent and the resulting ACK is legitimately a protocol violation at that client.
score_if cap-ecn-ack-frame run_case cap-ecn-ack-frame cap cap_ecn_ack_frame
# T3: Three in-memory pairs that differ in exactly one setting. All three receivers advertise `initial_max_stream_data_bidi_remote = 1024` and are given a connection-level limit far too large to ever be the thing that bites; they are given `set_max_stream_window(1024)`, `(2048)` and `(8192)` respectively. Each runs eight identical rounds of "offer the sender the whole buffer, exchange, drain the receiver completely", and the grader records how many bytes the sender was allowed to place in each round. The pinned receiver must hand out exactly 1024 bytes in each of the eight rounds — the limit advances by one window each time, which is the previous milestone's behaviour and the floor this group holds the candidate to. For the other two the first round must still be 1024, the allowance must never go down, it must never exceed the maximum that receiver was configured with, it must reach that maximum before the eighth round, and across the whole run it must take only the values on the doubling ladder between the two — {1024, 2048} for the first and {1024, 2048, 4096, 8192} for the second, and no value in between. Raising the maximum must move strictly more data in the same eight rounds, and the 8192 receiver must move at least four times what the pinned one moved. A receiver that ignores `set_max_stream_window` fails the pinned run and the never-exceeds bound; a receiver that never grows the window fails the ladder and the reaches-its-maximum bound; a receiver that grows the window by something other than doubling fails the ladder. The window is deliberately small enough that the initial congestion window can never be the limiter, so every number in the run is a statement about flow control. A fourth, separate run repeats the 8192 case but pins the connection-level ceiling to exactly that same 8192 instead of to the oversized value the first three runs use — the tightest ceiling a single-stream connection could need. It must reach the same {1024, 2048, 4096, 8192} ladder and the same eighth-round maximum as the third run: the connection window, kept at or above the largest stream window in play, must not throttle a stream window that grows up to and stays within it.
score_if cap-stream-window-autotune run_case cap-stream-window-autotune cap cap_stream_window_autotune
# T3: What a reader learns when the writer resets the stream. The grader has the client send 100 bytes on stream 0 without finishing it, lets the server read them, then has the client reset the stream with application error code `0xbeef` and exchanges again. The reset stream must first be offered to the application as readable — that is the path the reset travels — and `stream_recv` on it must then return `Err(Error::StreamReset(0xbeef))`, the exact variant carrying the exact code. The group also requires that the reset is reported once rather than repeatedly: having handed the reset over, the stream must drop out of `readable()` and must not come back into it however much more is exchanged. Asking the stream again must keep returning the same `Error::StreamReset(0xbeef)` rather than data or `Error::Done`. Finally a second, untouched stream on the same connection must still deliver its data and its `fin`, and neither endpoint may close. At the previous milestone there is no such variant and a reset stream simply goes quiet.
score_if cap-stream-reset-error run_case cap-stream-reset-error cap cap_stream_reset_error
# T3: The peer's SETTINGS frame, read back exactly as it arrived. The grader drives the candidate's transport `Connection` directly on the client side — no HTTP/3 connection there — and writes an HTTP/3 control stream by hand onto client uni-directional stream 2: the stream type varint `0x00`, then a SETTINGS frame carrying four pairs in this order, one of them an identifier no implementation recognises: ```text (0x01, 4096) QPACK_MAX_TABLE_CAPACITY (0x1f * 3 + 0x21, 0xdead) a reserved "grease" identifier (0x06, 1024) MAX_FIELD_SECTION_SIZE (0x07, 12) QPACK_BLOCKED_STREAMS ``` The server side is a real `h3::Connection`. After the exchange, `peer_settings_raw()` must return `Some` of exactly those four pairs in exactly that order — the unknown identifier included and not filtered out, the order preserved rather than sorted or canonicalised. The group also requires that polling the server raises no error, because an unrecognised SETTINGS identifier must be ignored rather than rejected, and that `peer_settings_raw()` was `None` before the frame arrived. A "grease" identifier is not the only kind of unrecognised one: the HTTP/2- reserved identifiers (`0x0`, `0x2`, `0x3`, `0x4`, `0x5`) are still a connection error under RFC 9114 Section 7.2.4.1. On a second, independent pair — SETTINGS may only be sent once per control stream — the grader writes a control stream carrying only `(0x02, 1)` and requires the server's poll to raise exactly `h3::Error::SettingsError`. Separately, this milestone renames `set_max_header_list_size` to `set_max_field_section_size` on `h3::Config`, and the rename is not merely cosmetic: on a third pair, built with the server's own `h3::Config` carrying a small `set_max_field_section_size` limit, a request whose header block exceeds that limit must still raise `h3::Error::ExcessiveLoad` when the server polls it, exactly as `set_max_header_list_size` did at the previous milestone. Of the three identifiers this implementation recognises by number (`0x1`/QPACK_MAX_TABLE_CAPACITY, `0x6`/MAX_FIELD_SECTION_SIZE and `0x7`/QPACK_BLOCKED_STREAMS), only `0x6` has an effect reachable through the public API at this milestone: this quiche version has no QPACK dynamic table implementation, so `0x1` and `0x7` are accepted, stored and returned by `peer_settings_raw()` exactly like any other identifier but drive no further observable behaviour. That is why this group's functional-effect case is built around `0x6` specifically rather than a generic "recognised identifiers take effect".
score_if cap-h3-peer-settings-raw run_case cap-h3-peer-settings-raw cap cap_h3_peer_settings_raw

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
